 * NOTE: With 1-second candles, the value equals the candle count.
 * The "Seconds" naming is semantically correct for 1s data.
 */
function parseOrbConfig(strategyParams?: Record<string, unknown>): OrbConfig {
  // Support both Seconds and legacy Minutes field names (no conversion, same semantics)
  const orbWindowSeconds = strategyParams?.orbWindowSeconds as number
    ?? strategyParams?.orbWindowMinutes as number
    ?? ORB_DEFAULTS.orbWindowSeconds;
  const retestTimeoutSeconds = strategyParams?.retestTimeoutSeconds as number
    ?? strategyParams?.retestTimeoutMinutes as number
    ?? ORB_DEFAULTS.retestTimeoutSeconds;
  const avoidFirstSeconds = strategyParams?.avoidFirstSeconds as number
    ?? strategyParams?.avoidFirstMinutes as number
    ?? ORB_DEFAULTS.avoidFirstSeconds;

  return {
    orbWindowSeconds: Math.max(1, Math.floor(orbWindowSeconds)),
    breakoutBufferAtr: strategyParams?.breakoutBufferAtr as number ?? ORB_DEFAULTS.breakoutBufferAtr,
    confirmationMode: (strategyParams?.confirmationMode as string ?? ORB_DEFAULTS.confirmationMode) === "two_closes" ? "two_closes" : "close",
    requireRetest: strategyParams?.requireRetest as boolean ?? ORB_DEFAULTS.requireRetest,
    retestTimeoutSeconds: Math.max(1, Math.floor(retestTimeoutSeconds)),
    avoidFirstSeconds: Math.max(0, Math.floor(avoidFirstSeconds)),
  };
}

