/**
 * =============================================================================
 * STEPPED STOP LOSS HELPER
 * =============================================================================
 *
 * Shared logic for stepped stop loss (profit-locking) used by multiple strategies.
 * Single source of truth for AC-6 compliance.
 *
 * ## How Stepped SL Works
 *
 * When price moves in your favor, the stop loss "steps up" to lock in profits:
 * - Config: `{ "20": 2, "25": 10 }` means:
 *   - At 20pts profit → lock in 2pts (SL moves to entry + 2)
 *   - At 25pts profit → lock in 10pts (SL moves to entry + 10)
 * - SL only tightens; it never loosens back.
 *
 * @module steppedStopLoss
 */

import type { Candle } from "../../backtest";

// =============================================================================
// TYPES
// =============================================================================

/** Configuration for stepped stop loss */
export interface SteppedSlConfig {
  /** Maps profit threshold (string) to profit to lock (number) */
  thresholds: Record<string, number>;
}

/** State tracking for stepped SL during a trade */
export interface SteppedSlState {
  /** Current SL price (updated as thresholds are crossed) */
  currentSlPrice: number;
  /** Maximum unrealized profit reached (for longs: max high - entry) */
  maxUnrealizedProfit: number;
  /** History of SL changes for UI visualization */
  slChanges: Array<{
    timestamp: string;
    slPrice: number;
    profitLocked: number;
    threshold: number;
  }>;
}

/** Result of processing a candle for stepped SL */
export interface SteppedSlUpdate {
  /** Whether SL was updated on this candle */
  updated: boolean;
  /** New SL price (same as old if not updated) */
  newSlPrice: number;
  /** Current unrealized profit for this candle */
  unrealizedProfit: number;
  /** Profit locked if updated, undefined otherwise */
  profitLocked?: number;
  /** Threshold that was crossed if updated */
  thresholdCrossed?: number;
}

// =============================================================================
// MAIN FUNCTIONS
// =============================================================================

/**
 * Parse and validate stepped SL configuration.
 *
 * @param config - Raw config object like `{"20": 2, "25": 10}`
 * @returns Parsed config with sorted thresholds, or null if no valid config
 */
export function parseSteppedSlConfig(
  config?: Record<string, number>
): { thresholds: number[]; config: Record<string, number> } | null {
  if (!config || typeof config !== "object") {
    return null;
  }

  const thresholds = Object.keys(config)
    .map(k => Number(k))
    .filter(k => !isNaN(k) && k > 0)
    .sort((a, b) => a - b);

  if (thresholds.length === 0) {
    return null;
  }

  return { thresholds, config };
}

/**
 * Initialize stepped SL state for a new trade.
 *
 * @param initialSlPrice - Initial stop loss price
 * @returns Initial state object
 */
export function initSteppedSlState(initialSlPrice: number): SteppedSlState {
  return {
    currentSlPrice: initialSlPrice,
    maxUnrealizedProfit: 0,
    slChanges: [],
  };
}

/**
 * Process a candle for stepped SL updates.
 *
 * Call this for each candle during exit scanning to update SL based on profit.
 *
 * @param candle - Current candle
 * @param entryPrice - Trade entry price
 * @param direction - Trade direction ("long" or "short")
 * @param state - Current stepped SL state (will NOT be mutated)
 * @param config - Stepped SL config (thresholds and profit-to-lock mapping)
 * @returns Update result with new state values
 */
export function processSteppedSl(
  candle: Candle,
  entryPrice: number,
  direction: "long" | "short",
  state: SteppedSlState,
  config: { thresholds: number[]; config: Record<string, number> }
): SteppedSlUpdate {
  // Calculate unrealized profit for this candle
  let unrealizedProfit: number;
  if (direction === "long") {
    // For longs: profit = highest price reached - entry price
    const candleHighProfit = candle.high - entryPrice;
    unrealizedProfit = Math.max(state.maxUnrealizedProfit, candleHighProfit);
  } else {
    // For shorts: profit = entry price - lowest price reached
    const candleLowProfit = entryPrice - candle.low;
    unrealizedProfit = Math.max(state.maxUnrealizedProfit, candleLowProfit);
  }

  let currentSlPrice = state.currentSlPrice;
  let updated = false;
  let profitLocked: number | undefined;
  let thresholdCrossed: number | undefined;

  // Check each threshold (sorted ascending)
  for (const threshold of config.thresholds) {
    if (unrealizedProfit >= threshold) {
      const profitToLock = config.config[String(threshold)];
      if (profitToLock != null) {
        // Calculate new SL price
        const newSlPrice = direction === "long"
          ? entryPrice + profitToLock
          : entryPrice - profitToLock;

        // Only update if new SL is better (higher for longs, lower for shorts)
        const shouldUpdate = direction === "long"
          ? newSlPrice > currentSlPrice
          : newSlPrice < currentSlPrice;

        if (shouldUpdate) {
          currentSlPrice = newSlPrice;
          updated = true;
          profitLocked = profitToLock;
          thresholdCrossed = threshold;
        }
      }
    }
  }

  return {
    updated,
    newSlPrice: currentSlPrice,
    unrealizedProfit,
    profitLocked,
    thresholdCrossed,
  };
}

/**
 * Apply a stepped SL update to state.
 *
 * @param state - Current state (will NOT be mutated)
 * @param update - Update result from processSteppedSl
 * @param timestamp - Candle timestamp for change tracking
 * @returns New state with updates applied
 */
export function applySteppedSlUpdate(
  state: SteppedSlState,
  update: SteppedSlUpdate,
  timestamp: string
): SteppedSlState {
  const newState: SteppedSlState = {
    currentSlPrice: update.newSlPrice,
    maxUnrealizedProfit: update.unrealizedProfit,
    slChanges: [...state.slChanges],
  };

  if (update.updated && update.profitLocked !== undefined && update.thresholdCrossed !== undefined) {
    newState.slChanges.push({
      timestamp,
      slPrice: update.newSlPrice,
      profitLocked: update.profitLocked,
      threshold: update.thresholdCrossed,
    });
  }

  return newState;
}

/**
 * =============================================================================
 * UNIT TESTS: Stepped Stop Loss Helper
 * =============================================================================
 *
 * Tests for the shared stepped SL logic (AC-6).
 */

import { describe, it, expect } from "vitest";
import {
  parseSteppedSlConfig,
  initSteppedSlState,
  processSteppedSl,
  applySteppedSlUpdate,
  type SteppedSlState,
} from "../steppedStopLoss";
import type { Candle } from "../../../backtest";

// =============================================================================
// HELPER FUNCTIONS
// =============================================================================

function createCandle(high: number, low: number, time = "2025-01-02T09:35:00-05:00"): Candle {
  return {
    time,
    open: (high + low) / 2,
    high,
    low,
    close: (high + low) / 2,
    volume: 100,
  };
}

// =============================================================================
// TESTS
// =============================================================================

describe("Stepped Stop Loss Helper", () => {
  describe("parseSteppedSlConfig", () => {
    it("parses valid config with sorted thresholds", () => {
      const result = parseSteppedSlConfig({ "25": 10, "20": 2, "30": 15 });

      expect(result).not.toBeNull();
      expect(result!.thresholds).toEqual([20, 25, 30]);
      expect(result!.config).toEqual({ "25": 10, "20": 2, "30": 15 });
    });

    it("returns null for undefined config", () => {
      expect(parseSteppedSlConfig(undefined)).toBeNull();
    });

    it("returns null for empty config", () => {
      expect(parseSteppedSlConfig({})).toBeNull();
    });

    it("filters out invalid threshold keys", () => {
      const result = parseSteppedSlConfig({ "20": 2, "invalid": 5, "-10": 1 });

      expect(result).not.toBeNull();
      expect(result!.thresholds).toEqual([20]);
    });
  });

  describe("initSteppedSlState", () => {
    it("initializes state with given SL price", () => {
      const state = initSteppedSlState(95);

      expect(state.currentSlPrice).toBe(95);
      expect(state.maxUnrealizedProfit).toBe(0);
      expect(state.slChanges).toEqual([]);
    });
  });

  describe("processSteppedSl - Long trades", () => {
    const config = parseSteppedSlConfig({ "20": 2, "25": 10 })!;

    it("tightens SL when threshold is crossed", () => {
      const state = initSteppedSlState(90); // Entry at 100, initial SL at 90
      const entryPrice = 100;

      // Candle reaches 120 (20pts profit) - should trigger first threshold
      const candle = createCandle(120, 115);
      const update = processSteppedSl(candle, entryPrice, "long", state, config);

      expect(update.updated).toBe(true);
      expect(update.newSlPrice).toBe(102); // entry + 2 (lock 2pts)
      expect(update.profitLocked).toBe(2);
      expect(update.thresholdCrossed).toBe(20);
    });

    it("does not loosen SL after it has been tightened", () => {
      // Start with already tightened SL
      const state: SteppedSlState = {
        currentSlPrice: 102, // Already locked 2pts
        maxUnrealizedProfit: 22,
        slChanges: [],
      };
      const entryPrice = 100;

      // Price retraces - profit drops but SL should stay at 102
      const candle = createCandle(115, 110); // Only 15pts profit now
      const update = processSteppedSl(candle, entryPrice, "long", state, config);

      expect(update.updated).toBe(false);
      expect(update.newSlPrice).toBe(102); // Unchanged
    });

    it("applies higher threshold when multiple are crossed", () => {
      const state = initSteppedSlState(90);
      const entryPrice = 100;

      // Candle reaches 130 (30pts profit) - both 20 and 25 thresholds crossed
      const candle = createCandle(130, 125);
      const update = processSteppedSl(candle, entryPrice, "long", state, config);

      expect(update.updated).toBe(true);
      expect(update.newSlPrice).toBe(110); // entry + 10 (lock 10pts from 25 threshold)
      expect(update.profitLocked).toBe(10);
      expect(update.thresholdCrossed).toBe(25);
    });
  });

  describe("processSteppedSl - Short trades", () => {
    const config = parseSteppedSlConfig({ "20": 2, "25": 10 })!;

    it("tightens SL when threshold is crossed", () => {
      const state = initSteppedSlState(110); // Entry at 100, initial SL at 110
      const entryPrice = 100;

      // Candle reaches 80 (20pts profit for short) - should trigger first threshold
      const candle = createCandle(85, 80);
      const update = processSteppedSl(candle, entryPrice, "short", state, config);

      expect(update.updated).toBe(true);
      expect(update.newSlPrice).toBe(98); // entry - 2 (lock 2pts)
      expect(update.profitLocked).toBe(2);
      expect(update.thresholdCrossed).toBe(20);
    });

    it("does not loosen SL after it has been tightened", () => {
      const state: SteppedSlState = {
        currentSlPrice: 98, // Already locked 2pts
        maxUnrealizedProfit: 22,
        slChanges: [],
      };
      const entryPrice = 100;

      // Price retraces up - profit drops but SL should stay at 98
      const candle = createCandle(95, 90); // Only 10pts profit now
      const update = processSteppedSl(candle, entryPrice, "short", state, config);

      expect(update.updated).toBe(false);
      expect(update.newSlPrice).toBe(98); // Unchanged
    });

    it("applies higher threshold when multiple are crossed", () => {
      const state = initSteppedSlState(110);
      const entryPrice = 100;

      // Candle reaches 70 (30pts profit) - both thresholds crossed
      const candle = createCandle(75, 70);
      const update = processSteppedSl(candle, entryPrice, "short", state, config);

      expect(update.updated).toBe(true);
      expect(update.newSlPrice).toBe(90); // entry - 10 (lock 10pts)
      expect(update.profitLocked).toBe(10);
      expect(update.thresholdCrossed).toBe(25);
    });
  });

  describe("applySteppedSlUpdate", () => {
    it("updates state and tracks changes when SL is updated", () => {
      const state = initSteppedSlState(90);
      const update = {
        updated: true,
        newSlPrice: 102,
        unrealizedProfit: 22,
        profitLocked: 2,
        thresholdCrossed: 20,
      };

      const newState = applySteppedSlUpdate(state, update, "2025-01-02T09:35:30-05:00");

      expect(newState.currentSlPrice).toBe(102);
      expect(newState.maxUnrealizedProfit).toBe(22);
      expect(newState.slChanges).toHaveLength(1);
      expect(newState.slChanges[0]).toEqual({
        timestamp: "2025-01-02T09:35:30-05:00",
        slPrice: 102,
        profitLocked: 2,
        threshold: 20,
      });
    });

    it("does not track changes when SL is not updated", () => {
      const state: SteppedSlState = {
        currentSlPrice: 102,
        maxUnrealizedProfit: 20,
        slChanges: [{ timestamp: "earlier", slPrice: 102, profitLocked: 2, threshold: 20 }],
      };
      const update = {
        updated: false,
        newSlPrice: 102,
        unrealizedProfit: 15,
      };

      const newState = applySteppedSlUpdate(state, update, "2025-01-02T09:36:00-05:00");

      expect(newState.slChanges).toHaveLength(1); // No new change added
    });
  });

  describe("No config scenario", () => {
    it("returns no update when config is not provided", () => {
      const config = parseSteppedSlConfig(undefined);
      expect(config).toBeNull();
      // Without config, stepped SL should not be applied
    });
  });
});

