/**
 * Step 7: Scan for exit condition (TP hit, SL hit, or EOD).
 *
 * Includes:
 * - Stepped SL support (via shared helper)
 * - Intrabar resolution for same-candle exits
 */
function scanExit(
  state: TradingState,
  entry: EntrySignal,
  tpPrice: number,
  initialSlPrice: number
): ExitResult {
  const { candles, longTrigger, shortTrigger, stopLossByProfitThreshold, log } = state;
  const { candleIndex: triggerCandleIndex, direction, entryPrice } = entry;

  // Initialize stepped SL if configured
  const steppedSlConfig = parseSteppedSlConfig(stopLossByProfitThreshold);
  let steppedSlState = initSteppedSlState(initialSlPrice);
  let currentSlPrice = initialSlPrice;

  if (steppedSlConfig) {
    log(`  Stepped SL enabled: thresholds=[${steppedSlConfig.thresholds.join(", ")}]`);
  }

  let exitCandleIndex = -1;
  let exitNote: "PT Hit" | "SL Hit" | "EOD Push" = "EOD Push";
  let exitPrice = entryPrice;
  let exitTimestamp = candles[candles.length - 1].time;
  let exitSlippage = 0;

  for (let i = triggerCandleIndex; i < candles.length; i++) {
    const candle = candles[i];

    // Process stepped SL before checking exits (for all candles after entry)
    if (steppedSlConfig && i > triggerCandleIndex) {
      const update = processSteppedSl(candle, entryPrice, direction, steppedSlState, steppedSlConfig);
      if (update.updated) {
        log(`  Stepped SL: threshold ${update.thresholdCrossed}pts crossed, locking ${update.profitLocked}pts. SL: ${currentSlPrice.toFixed(2)} → ${update.newSlPrice.toFixed(2)}`);
      }
      steppedSlState = applySteppedSlUpdate(steppedSlState, update, candle.time);
      currentSlPrice = steppedSlState.currentSlPrice;
    }

    // Same-candle intrabar resolution
    if (i === triggerCandleIndex) {
      const entryLevel = direction === "long" ? longTrigger : shortTrigger;
      const intrabarResult = resolveIntrabarDirectional({
        candle: { O: candle.open, H: candle.high, L: candle.low, C: candle.close, V: candle.volume || 0 },
        side: direction,
        entryLevel,
        stopLevel: currentSlPrice,
        targetLevel: tpPrice,
      });

      if (intrabarResult.event === "FILL_STOP_SAME_BAR") {
        exitCandleIndex = i;
        exitTimestamp = candle.time;
        exitNote = "SL Hit";
        exitPrice = intrabarResult.exitFill!;
        log(`  Exit: ${exitNote} at candle[${i}], price=${exitPrice} (intrabar)`);
        break;
      } else if (intrabarResult.event === "FILL_TARGET_SAME_BAR") {
        exitCandleIndex = i;
        exitTimestamp = candle.time;
        exitNote = "PT Hit";
        exitPrice = intrabarResult.exitFill!;
        log(`  Exit: ${exitNote} at candle[${i}], price=${exitPrice} (intrabar)`);
        break;
      }
      continue;
    }

    // Standard exit check for subsequent candles (using current SL which may have been stepped)
    let tpHit = false;
    let slHit = false;

    if (direction === "long") {
      tpHit = candle.high >= tpPrice;
      slHit = candle.low <= currentSlPrice;
    } else {
      tpHit = candle.low <= tpPrice;
      slHit = candle.high >= currentSlPrice;
    }

    if (tpHit || slHit) {
      exitCandleIndex = i;
      exitTimestamp = candle.time;

      if (tpHit && slHit) {
        // Conservative: SL wins
        exitNote = "SL Hit";
        exitSlippage = calculateSlSlippage(direction);
        exitPrice = direction === "long" ? currentSlPrice - exitSlippage : currentSlPrice + exitSlippage;
      } else if (slHit) {
        exitNote = "SL Hit";
        exitSlippage = calculateSlSlippage(direction);
        exitPrice = direction === "long" ? currentSlPrice - exitSlippage : currentSlPrice + exitSlippage;
      } else {
        exitNote = "PT Hit";
        exitSlippage = calculateTpSlippage(direction);
        exitPrice = direction === "long" ? tpPrice - exitSlippage : tpPrice + exitSlippage;
      }
      log(`  Exit: ${exitNote} at candle[${i}], price=${exitPrice}`);
      break;
    }
  }

  // Calculate net P&L
  const net = direction === "long"
    ? exitPrice - entryPrice
    : entryPrice - exitPrice;

